const uint lane = thread_index_in_simdgroup;
const uint row0 = (threadgroup_position_in_grid.x * 8 + simdgroup_index_in_threadgroup) * 4;
float acc[4] = {0.f, 0.f, 0.f, 0.f};
uint nr[4];
for (int r = 0; r < 4; r++) {
    uint n = row0 + r;
    nr[r] = n >= (uint)N ? (uint)(N - 1) : n;  // clamp; result discarded
}
int k0 = lane * 16;
uint2 w[4];
float s[4], b[4];
if (k0 < K) {
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        w[r] = ld2(wq + nr[r] * (K / 8) + (k0 >> 3));
        s[r] = float(scales[nr[r] * (K / 64) + (k0 >> 6)]);
        b[r] = float(biases[nr[r] * (K / 64) + (k0 >> 6)]);
    }
}
for (; k0 < K; k0 += 512) {
    // prefetch next iteration (reload current if past the end; harmless)
    int kn = k0 + 512;
    if (kn >= K) kn = k0;
    uint2 wn[4];
    float sn[4], bn[4];
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        wn[r] = ld2(wq + nr[r] * (K / 8) + (kn >> 3));
        sn[r] = float(scales[nr[r] * (K / 64) + (kn >> 6)]);
        bn[r] = float(biases[nr[r] * (K / 64) + (kn >> 6)]);
    }
    float xp[16];
    float xs = 0.f;
    for (int j = 0; j < 2; j++) {
        float sc = 1.f;
        for (int i = 0; i < 8; i++) {
            float v = float(x[k0 + j * 8 + i]);
            xs += v;
            xp[j * 8 + i] = v * sc;
            sc *= 0.0625f;
        }
    }
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        float d = 0.f;
        for (int i = 0; i < 8; i++) {
            const uint m = 0xFu << (4 * i);
            d += xp[i] * float(w[r].x & m);
            d += xp[8 + i] * float(w[r].y & m);
        }
        acc[r] += s[r] * d + b[r] * xs;
    }
    #pragma unroll
    for (int r = 0; r < 4; r++) { w[r] = wn[r]; s[r] = sn[r]; b[r] = bn[r]; }
}
for (int r = 0; r < 4; r++) {
    float t = simd_sum(acc[r]);
    if (lane == 0 && row0 + r < (uint)N) out[row0 + r] = half(t);
}
